def find_magic_sequence(n=4):
    solutions = []
    # Each x[i] is between 0 and n
    for x0 in range(n+1):
        for x1 in range(n+1):
            for x2 in range(n+1):
                for x3 in range(n+1):
                    seq = [x0, x1, x2, x3]
                    # Check sum condition first
                    if sum(seq) != n:
                        continue
                    # Check counts
                    ok = True
                    for i in range(n):
                        if seq[i] != seq.count(i):
                            ok = False
                            break
                    if ok:
                        solutions.append(seq)
    return solutions

print(find_magic_sequence(4))
